PROGRAM ST_L04_PALLVAXLING
VAR
    steg     : INT := 0;
    tmrKolli : TON;
END_VAR

tmrKolli(IN := (steg = 1) AND NOT tmrKolli.Q AND (ST180_TOT_CNT < 24) AND (ST180_INF_CNT > 0), PT := T#5500ms);

IF NOT EMG_OK THEN
    ST180_MAG_REQ  := FALSE;
    ST180_PLT_OUT  := FALSE;
    ST180_PLT_IN   := FALSE;
    ST180_SWP_BUSY := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST180_MAG_REQ  := FALSE;
            ST180_PLT_OUT  := FALSE;
            ST180_PLT_IN   := FALSE;
            ST180_SWP_BUSY := FALSE;
            ST180_TOT_CNT  := 0;
            IF EMG_OK AND ST180_PLT_PRS THEN
                steg := 1;
            END_IF;
        1:
            IF tmrKolli.Q THEN
                ST180_TOT_CNT := ST180_TOT_CNT + 1;
            END_IF;

            IF ST180_TOT_CNT >= 16 AND ST180_TOT_CNT < 24 THEN
                ST180_MAG_REQ := TRUE;
            END_IF;

            (* Vaxlingen far starta forst nar magasinet har en tom pall klar:
               sekvensen "vanta pa ST180_MAG_RDY medan palleteringen fortsatter".
               Utan den kors den fulla pallen ut mot en tom utmatare och
               stationen star utan pall langre an vaxlingens 22,0 s. *)
            IF ST180_TOT_CNT >= 24 AND ST180_MAG_RDY THEN
                ST180_SWP_BUSY := TRUE;
                ST180_PLT_OUT  := TRUE;
                steg := 2;
            END_IF;
        2:
            IF ST180_PLT_GONE THEN
                ST180_PLT_OUT := FALSE;
                ST180_PLT_IN  := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST180_PLT_PRS THEN
                ST180_PLT_IN   := FALSE;
                ST180_SWP_BUSY := FALSE;
                ST180_MAG_REQ  := FALSE;
                ST180_TOT_CNT  := 0;
                steg := 1;
            END_IF;
    END_CASE;
END_IF;
END_PROGRAM

